using OcctSharp.PolygonBoundaries;
using OcctSharp.PolyWorkspaces;
using OcctSharp.MeshingWorkspaces;
using OcctSharp.Values;
namespace OcctSharp.Tests.Shared;
internal static class BatchAYBoundaryWorkflow {
 internal static void Run(){using var box=ShapeFactory.CreateBox(2,3,4);using var meshing=ControlledMeshing.Run(box);if(!meshing.IsDone||!meshing.HasCompleteTriangulation)throw new InvalidOperationException("AY exact source meshing incomplete.");using var shape=meshing.CopyShape();var mesh=MeshTopology.SnapshotExisting(shape).Mesh;using var data=PolyDataWorkspaces.FromMesh(mesh);using var native=data.CopyTriangulation();var triangle=mesh.Triangles[0];using var boundary=PolygonBoundaryWorkspaces.OnTriangulation(native,[triangle.A,triangle.B,triangle.C,triangle.A],[0,1,2,3],.05);if(boundary.Points.Count!=4||boundary.Points[0]!=boundary.Points[3]||boundary.AssociatedTriangulationNodeCount!=mesh.Positions.Count||boundary.Parameters?.Count!=4||boundary.NodeIndices[1]!=triangle.B)throw new InvalidOperationException("AY copied polygon/mesh domain mismatch.");using var spatial=PolygonBoundaryWorkspaces.Spatial(boundary.Points,boundary.Parameters,.05);using var loops=PolygonBoundaryWorkspaces.SimpleLoops([new(triangle.A,triangle.B),new(triangle.B,triangle.C),new(triangle.C,triangle.A)]);if(loops.Loops.Count!=1||loops.Loops[0].Count!=4||loops.NativeLoopResultFlags!=1)throw new InvalidOperationException("AY bounded native simple loop failed.");using var first=boundary.CopyTriangulation();using var second=boundary.CopyTriangulation();native.Dispose();data.Dispose();boundary.Dispose();box.Dispose();meshing.Dispose();shape.Dispose();using var independent=PolyDataWorkspaces.Copy(first);using var other=PolyDataWorkspaces.Copy(second);if(independent.Mesh.Triangles.Count!=mesh.Triangles.Count||other.Mesh.Positions.Count!=mesh.Positions.Count||!spatial.Points.SequenceEqual(boundary.Points))throw new InvalidOperationException("AY independent polygon/triangulation lifetime failed.");}
}
